// Validate and normalize input
const body = $input.first().json;

if (!body.account_id) throw new Error('account_id is required');
if (!body.transcript && !body.transcript_text) throw new Error('transcript or transcript_text is required');

return [{
  json: {
    account_id: body.account_id,
    transcript: body.transcript_text || body.transcript,
    stage: 'demo',
    timestamp: new Date().toISOString()
  }
}];

// Generate Retell Agent Spec from memo
const memo = $input.first().json.memo;
const accountId = memo.account_id;

const bh = memo.business_hours || {};
const er = memo.emergency_routing_rules || {};
const ctr = memo.call_transfer_rules || {};

const agentSpec = {
  agent_name: `Clara – ${memo.company_name || accountId}`,
  version: 'v1',
  account_id: accountId,
  generated_at: new Date().toISOString(),
  voice_style: { gender: 'female', tone: 'professional_warm', speed: 'normal' },
  key_variables: {
    timezone: bh.timezone,
    business_hours_start: bh.start,
    business_hours_end: bh.end,
    business_days: bh.days,
    emergency_primary_phone: er.primary_phone,
    transfer_timeout_seconds: ctr.timeout_seconds || 30
  },
  system_prompt: `[Generated by pipeline — see full spec in outputs/${accountId}/v1/agent_spec.json]`,
  call_transfer_protocol: { timeout_seconds: ctr.timeout_seconds || 30 },
  version_notes: 'v1: Based on demo call. Preliminary configuration. Confirm all routing on onboarding.'
};

return [{ json: { memo, agent_spec: agentSpec, account_id: accountId } }];

// Create task tracker entry (Asana-compatible format)
const item = $input.first().json;
const memo = item.memo;

const unknowns = (memo.questions_or_unknowns || []).length;
const taskEntry = {
  title: `[Clara] Demo processed: ${memo.company_name || item.account_id}`,
  account_id: item.account_id,
  status: 'pending_onboarding',
  created_at: new Date().toISOString(),
  notes: [
    `v1 memo generated from demo call.`,
    `${unknowns} open question(s) flagged.`,
    unknowns > 0 ? `Unknowns: ${memo.questions_or_unknowns.join('; ')}` : 'No blockers.',
    'Awaiting onboarding call to generate v2.'
  ].join(' '),
  outputs: {
    memo_path: `/outputs/accounts/${item.account_id}/v1/account_memo.json`,
    spec_path: `/outputs/accounts/${item.account_id}/v1/agent_spec.json`
  }
};

return [{ json: taskEntry }];

const body = $input.first().json;
if (!body.account_id) throw new Error('account_id required');
if (!body.transcript && !body.transcript_text) throw new Error('transcript required');

const fs = require('fs');
const memoPath = `/outputs/accounts/${body.account_id}/v1/account_memo.json`;

let existingMemo = null;
try {
  existingMemo = JSON.parse(fs.readFileSync(memoPath, 'utf8'));
} catch(e) {
  throw new Error(`v1 memo not found for ${body.account_id}. Run Pipeline A first.`);
}

return [{
  json: {
    account_id: body.account_id,
    transcript: body.transcript_text || body.transcript,
    existing_memo: existingMemo,
    stage: 'onboarding',
    timestamp: new Date().toISOString()
  }
}];

const result = $input.first().json;
const v2Memo = result.updated_memo;
const changes = result.changes || [];

// Generate changelog markdown
const lines = [
  `# Changelog: ${v2Memo.company_name} (${v2Memo.account_id})`,
  `**Generated:** ${new Date().toISOString()}`,
  `**Change:** v1 → v2 (${changes.length} field changes)`,
  '',
  '## Changes',
  ...changes.map(c => `- **${c.field}**: ${JSON.stringify(c.old_value)} → ${JSON.stringify(c.new_value)}`)
];

return [{
  json: {
    v2_memo: v2Memo,
    changes,
    changelog_md: lines.join('\n'),
    account_id: v2Memo.account_id
  }
}];

const item = $input.first().json;
const memo = item.v2_memo;

const bh = memo.business_hours || {};
const er = memo.emergency_routing_rules || {};
const ctr = memo.call_transfer_rules || {};

const agentSpec = {
  agent_name: `Clara – ${memo.company_name}`,
  version: 'v2',
  account_id: memo.account_id,
  generated_at: new Date().toISOString(),
  voice_style: { gender: 'female', tone: 'professional_warm', speed: 'normal' },
  key_variables: {
    timezone: bh.timezone,
    business_hours_start: bh.start,
    business_hours_end: bh.end,
    business_days: bh.days,
    emergency_primary_phone: er.primary_phone,
    emergency_secondary_phone: er.secondary_phone,
    transfer_timeout_seconds: ctr.timeout_seconds || 30
  },
  system_prompt: `[Onboarding-confirmed. See full spec in outputs/${memo.account_id}/v2/agent_spec.json]`,
  call_transfer_protocol: {
    timeout_seconds: ctr.timeout_seconds || 30,
    retries: ctr.retries || 1
  },
  version_notes: 'v2: Onboarding-confirmed. Production-ready.'
};

return [{ json: { ...item, agent_spec_v2: agentSpec } }];
